% calculates V system
% 2d rephasing and non-rephasing in time domain
% 1d linear in frequency domain
% follows Tekavec, 2007, but is auto-generated to avoid typos

function [one_trace_nr, one_trace_r, one_spec_1d] = core_formulas( ...
    mu, omega, omega21, omega43, t1, t2, t3, gamma, omega1)

% Input
% mu - 3x3 matrix of transition dipole moments
% omega - 3x3 matrix of transition frequencies
% omega21 - rotation frame frequency of first pulse pair
% omega43 - rotation frame frequency of second pulse pair
% t1, t2, t3 - delays between the pulses
% gamma - 3x3 matrix of diagonal and off-diagonal relaxation
% omega1 - frequency for linear spectrum

% 2d, non-rephasing 
one_trace_nr =  ... 
1.* mu(1,2).* exp(-1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1).* mu(1,2).* exp(-1 .* gamma(1,1) .* t2).* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1.* mu(1,2).* exp(-1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1).* mu(1,2).* exp(-1 .* gamma(1,1) .* t2).* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1.* mu(1,2).* exp(-1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1) .* -1 .* mu(1,2).* exp(-1 .* gamma(2,2) .* t2) .* -1 .* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1.* mu(1,2).* exp(-1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1) .* -1 .* mu(1,3).* exp(+1i .* (omega(2,3)  ).* t2).* exp(-1 .* gamma(2,3) .* t2) .* -1 .* mu(1,3).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1.* mu(1,3).* exp(-1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1).* mu(1,3).* exp(-1 .* gamma(1,1) .* t2).* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1.* mu(1,3).* exp(-1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1).* mu(1,3).* exp(-1 .* gamma(1,1) .* t2).* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1.* mu(1,3).* exp(-1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1) .* -1 .* mu(1,2).* exp(-1i .* (omega(2,3)  ).* t2).* exp(-1 .* gamma(2,3) .* t2) .* -1 .* mu(1,2).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1.* mu(1,3).* exp(-1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1) .* -1 .* mu(1,3).* exp(-1 .* gamma(3,3) .* t2) .* -1 .* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) ; 
 
% 2d, rephasing 
one_trace_r =  ... 
1 .* -1 .* mu(1,2).* exp(+1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1).* mu(1,2).* exp(-1 .* gamma(2,2) .* t2) .* -1 .* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1 .* -1 .* mu(1,2).* exp(+1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1).* mu(1,3).* exp(-1i .* (omega(2,3)  ).* t2).* exp(-1 .* gamma(2,3) .* t2) .* -1 .* mu(1,2).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1 .* -1 .* mu(1,2).* exp(+1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1) .* -1 .* mu(1,2).* exp(-1 .* gamma(1,1) .* t2).* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1 .* -1 .* mu(1,2).* exp(+1i .* (omega(1,2)  - omega21  ).* t1).* exp(-1 .* gamma(1,2) .* t1) .* -1 .* mu(1,2).* exp(-1 .* gamma(1,1) .* t2).* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1 .* -1 .* mu(1,3).* exp(+1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1).* mu(1,2).* exp(+1i .* (omega(2,3)  ).* t2).* exp(-1 .* gamma(2,3) .* t2) .* -1 .* mu(1,3).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1 .* -1 .* mu(1,3).* exp(+1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1).* mu(1,3).* exp(-1 .* gamma(3,3) .* t2) .* -1 .* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) + ... 
1 .* -1 .* mu(1,3).* exp(+1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1) .* -1 .* mu(1,3).* exp(-1 .* gamma(1,1) .* t2).* mu(1,2).* exp(-1i .* (omega(1,2)  - omega43  ).* t3).* exp(-1 .* gamma(1,2) .* t3) .* -1 .* mu(1,2) + ... 
1 .* -1 .* mu(1,3).* exp(+1i .* (omega(1,3)  - omega21  ).* t1).* exp(-1 .* gamma(1,3) .* t1) .* -1 .* mu(1,3).* exp(-1 .* gamma(1,1) .* t2).* mu(1,3).* exp(-1i .* (omega(1,3)  - omega43  ).* t3).* exp(-1 .* gamma(1,3) .* t3) .* -1 .* mu(1,3) ; 
 
% 1d, frequency domain 
one_spec_1d =  ... 
1.* mu(1,2).* 1i ./(+1 .* omega1 + -1 .* omega(1,2) + 1i .* gamma(1,2) )  .* -1 .* mu(1,2) + ... 
1.* mu(1,3).* 1i ./(+1 .* omega1 + -1 .* omega(1,3) + 1i .* gamma(1,3) )  .* -1 .* mu(1,3) ; 

end 